from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_modes = []
    for row in grid:
        color, count = Counter(row).most_common(1)[0]
        row_modes.append((color, count / w))
    line_color = max(
        {color for color, _ in row_modes},
        key=lambda color: max(ratio for mode, ratio in row_modes if mode == color),
    )
    fill_color = Counter(
        value for row in grid for value in row if value != line_color
    ).most_common(1)[0][0]
    row_lines = [r for r, row in enumerate(grid) if row.count(line_color) >= 0.8 * w]
    col_lines = [
        c for c in range(w)
        if sum(grid[r][c] == line_color for r in range(h)) >= 0.65 * h
    ]
    out = []
    for r1, r2 in zip(row_lines, row_lines[1:]):
        out_row = []
        for c1, c2 in zip(col_lines, col_lines[1:]):
            corners = [grid[r1][c1], grid[r1][c2], grid[r2][c1], grid[r2][c2]]
            if len(set(corners)) == 1 and corners[0] != line_color:
                out_row.append(corners[0])
            else:
                out_row.append(fill_color)
        out.append(out_row)
    while out and all(value == fill_color for value in out[0]):
        out.pop(0)
    while out and all(value == fill_color for value in out[-1]):
        out.pop()
    while out and out[0] and all(row[0] == fill_color for row in out):
        for row in out:
            row.pop(0)
    while out and out[0] and all(row[-1] == fill_color for row in out):
        for row in out:
            row.pop()
    return out or [[fill_color]]

